-- =====================================================================
-- Jeu de données de démonstration — lycée (généré le 2026-11-17)
--
-- À exécuter sur une base déjà migrée (tables créées par Flyway) et vide de
-- données métier. Rien ici n'est un vrai dossier : noms, notes et règlements
-- sont inventés.
--
--   psql -U lycee -h localhost -d lycee -f donnees-demo.sql
--
-- Contenu : 2 années scolaires (18 élèves par classe sur 8 classes cette année),
-- le personnel, les matières et coefficients, les notes du 1er trimestre,
-- la grille tarifaire, les plans de paiement, les frais, les échéanciers et
-- les règlements déjà encaissés.
-- =====================================================================

BEGIN;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM annee_scolaire) THEN
        RAISE EXCEPTION 'La base contient déjà des données : videz-la avant d''installer le jeu de démonstration (voir le README).';
    END IF;
END $$;




















UPDATE inscription SET plan_paiement_id = '9e7a3203-e9be-4038-8d29-78eb9100474c' WHERE id IN ('eefe1374-2300-4c7b-bb78-f19b3c70e3b0', '3562639a-fd06-4294-9f8a-0c90f7c5f424', 'fc7ff717-b101-4cfb-bef3-da9d48e7e089', 'acf83ccb-c230-4875-9f13-b6c605f677a0', '33172cf3-3024-460e-9f72-908993e574a0', 'f1733bb7-3f20-4bfd-a62c-fa0fb51808c9', 'ac142b0b-d981-433a-8f0d-06ab415741ad', 'c2b4bbff-66d2-4fbd-abdd-9d904b1779df', 'b9bf7e7d-91c4-4065-a535-72928ce7b4f2');

-- Un encaissement saisi en double, annulé par l'intendant : le reçu reste, les imputations sont retirées.
DELETE FROM imputation_paiement WHERE paiement_id = 'e2a81cdd-d5f7-4f01-a644-6b405fe61bd8';
UPDATE echeance_eleve e SET montant_paye = COALESCE((SELECT sum(i.montant) FROM imputation_paiement i WHERE i.echeance_eleve_id = e.id), 0) WHERE e.frais_eleve_id IN (SELECT id FROM frais_eleve WHERE inscription_id = 'eefe1374-2300-4c7b-bb78-f19b3c70e3b0');
UPDATE echeance_eleve e SET statut = CASE WHEN e.montant_paye >= e.montant_du THEN 'PAYEE' WHEN e.date_echeance < DATE '2026-11-17' THEN 'EN_RETARD' WHEN e.montant_paye > 0 THEN 'PARTIEL' ELSE 'A_VENIR' END WHERE e.frais_eleve_id IN (SELECT id FROM frais_eleve WHERE inscription_id = 'eefe1374-2300-4c7b-bb78-f19b3c70e3b0');
UPDATE paiement SET statut = 'ANNULE', motif_annulation = 'Encaissement saisi deux fois le même jour', annule_par = 'intendant' WHERE id = 'e2a81cdd-d5f7-4f01-a644-6b405fe61bd8';

COMMIT;
